const bWarm = makeBlob(255,196,138), bNeutral = makeBlob(226,204,182),
      bCool = makeBlob(152,174,212), bBlue    = makeBlob(118,148,204),
      bRed  = makeBlob(255,112, 96);

const EXT = 1.4, TEX = 1200;
const dust = document.createElement('canvas'); dust.width = dust.height = TEX;
{
