  const base = d.createRadialGradient(TEX/2, TEX/2, 0, TEX/2, TEX/2, EXT * TS * 0.99);
  base.addColorStop(0,    'rgba(255,224,188,0.15)');
  base.addColorStop(0.13, 'rgba(255,214,178,0.09)');
  base.addColorStop(0.38, 'rgba(172,182,208,0.045)');
  base.addColorStop(0.72, 'rgba(134,152,192,0.018)');
  base.addColorStop(1,    'rgba(128,146,186,0)');
