    spinVel = clamp(spinVel * 0.5 + (d / dtm) * 0.5, -2.5, 2.5);
    lastX = e.clientX; lastMoveT = now;
  } else {
    pNorm.x = clamp((e.clientX - W / 2) / (W / 2), -1.4, 1.4);
    pNorm.y = clamp((e.clientY - H / 2) / (H / 2), -1.4, 1.4);
