  ctx.save();
  ctx.translate(W / 2 + par.x, H / 2 + par.y);
  ctx.scale(1, incl);
  ctx.rotate(spin);
  ctx.scale(S, S);

  ctx.globalAlpha = 0.92 * fe;
  ctx.drawImage(dust, -EXT, -EXT, EXT * 2, EXT * 2);

