  let cg = ctx.createRadialGradient(0, 0, 0, 0, 0, 0.17 * pulse);
  cg.addColorStop(0,    'rgba(255,250,240,' + (0.72 * fe) + ')');
  cg.addColorStop(0.28, 'rgba(255,228,192,' + (0.32 * fe) + ')');
  cg.addColorStop(0.62, 'rgba(255,198,142,' + (0.11 * fe) + ')');
  cg.addColorStop(1,    'rgba(255,182,124,0)');
  ctx.globalAlpha = 1;
  ctx.fillStyle = cg;
  ctx.beginPath(); ctx.arc(0, 0, 0.17 * pulse, 0, TAU); ctx.fill();
  cg = ctx.createRadialGradient(0, 0, 0, 0, 0, 0.46);
  cg.addColorStop(0,   'rgba(255,214,168,' + (0.10 * fe) + ')');
  cg.addColorStop(0.5, 'rgba(252,202,152,' + (0.045 * fe) + ')');
  cg.addColorStop(1,   'rgba(250,196,148,0)');
  ctx.fillStyle = cg;
  ctx.beginPath(); ctx.arc(0, 0, 0.46, 0, TAU); ctx.fill();

  ctx.restore();

  // vignette
  ctx.globalCompositeOperation = 'source-over';
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.drawImage(vig, 0, 0);
}
requestAnimationFrame(frame);
